  const nodeIds = new Set<string>();
  for (const node of nodeList) {
    if (nodeIds.has(node.id)) return null;
    nodeIds.add(node.id);
  }
  const edges = graphRecord.edges.map(parseEdge);
  if (edges.some((edge) => edge === null)) return null;
  const edgeIdMap = new Map<string, string>();
  const edgeList = (edges as WorkspaceGraphEdge[]).map((edge) => {
    const source = nodeIdMap.get(edge.source) ?? edge.source;
    const target = nodeIdMap.get(edge.target) ?? edge.target;
    const id = edge.id === JSON.stringify([edge.source, edge.predicate, edge.target])
      ? JSON.stringify([source, edge.predicate, target]) : edge.id;
    edgeIdMap.set(edge.id, id);
    return {...edge, id, source, target};
  });
  const edgeIds = new Set<string>();
  for (const edge of edgeList) {
    if (
      edgeIds.has(edge.id) ||
      !nodeIds.has(edge.source) ||
      !nodeIds.has(edge.target)
    ) {
      return null;
    }
    edgeIds.add(edge.id);
  }
  const revision = finiteNumber(graphRecord.revision);
  if (revision === null || revision < 0 || !Number.isInteger(revision)) return null;
  const rawLinks = graphRecord.statementLinks ?? [];
  if (!Array.isArray(rawLinks) || rawLinks.length > MAX_EDGES) return null;
  const parsedLinks = rawLinks.map(parseStatementLink);
  if (parsedLinks.some((link) => link === null)) return null;
