  const mappedReference = (id: string) => nodeIdMap.get(id) ?? canonicalLegacyNodeId({id, kind: "blank", label: ""}, options.repositoryReferences === true, importScope);
  const statementLinks = (parsedLinks as WorkspaceStatementLink[]).map(link => {
    // Components need not have a card yet. Downgrade imported fixed references there as well, before a statement
    // card can materialize its missing endpoints into the graph.
    const migrate = (id: string) => nodeIdMap.get(id) ?? (parseFixedBlankNodeReference(id) ? mappedReference(id) : id);
    const source = migrate(link.source), subject = migrate(link.subject), object = migrate(link.object);
    const id = link.id === JSON.stringify([link.source, link.predicate, link.subject, link.statementPredicate, link.object])
      ? JSON.stringify([source, link.predicate, subject, link.statementPredicate, object]) : link.id;
    const statementEdgeId = edgeIdMap.get(link.statementEdgeId) ??
      (link.statementEdgeId === JSON.stringify([link.subject, link.statementPredicate, link.object])
        ? JSON.stringify([subject, link.statementPredicate, object]) : link.statementEdgeId);
    return {...link, id, source, subject, object, statementEdgeId};
  }).filter((link) => nodeIds.has(link.source));

  const transform =
    payload?.transform === undefined
      ? { x: 0, y: 0, k: 1 }
      : parseTransform(payload.transform);
