  const query = payload?.query === undefined ? "" : stringValue(payload.query);
  const endpointId =
    payload?.endpointId === undefined ? "wikidata-official" : stringValue(payload.endpointId, 256);
  const customUrl =
    payload?.customUrl === undefined ? "" : stringValue(payload.customUrl, 16_384);
