  const selectedNodeIds = Array.isArray(payload?.selectedNodeIds)
    ? [...new Set(payload.selectedNodeIds)]
        .map((nodeId) => nodeIdMap.get(nodeId) ?? nodeId)
        .filter(
          (nodeId): nodeId is string =>
            typeof nodeId === "string" && nodeIds.has(nodeId),
        )
    : [];
